// DaemonServiceServer is the server API for DaemonService service.
// All implementations must embed UnimplementedDaemonServiceServer
// for forward compatibility.
//
// The daemon that owns boxes on this Mac.
type DaemonServiceServer interface {
	GetVersion(context.Context, *GetVersionRequest) (*GetVersionResponse, error)
	ListBoxes(context.Context, *ListBoxesRequest) (*ListBoxesResponse, error)
	// Opens a box on this Mac: the resume rules, then a running box.
	OpenBox(context.Context, *OpenBoxRequest) (*OpenBoxResponse, error)
	// Saves and releases the box and stops it.
	CloseBox(context.Context, *CloseBoxRequest) (*CloseBoxResponse, error)
	// Makes a save point (File › Make Save Point).
	MakeSavePoint(context.Context, *MakeSavePointRequest) (*MakeSavePointResponse, error)
	// Revert To ▸ Last Save Point: saves the current home first, then restores
	// the newest save point.
	RevertToLastSavePoint(context.Context, *RevertToLastSavePointRequest) (*RevertToLastSavePointResponse, error)
	// Move To ▸: closes the box here and opens it on the target.
	MoveBox(context.Context, *MoveBoxRequest) (*MoveBoxResponse, error)
	// Attaches a terminal to the box's tmux session through the box agent.
	Terminal(grpc.BidiStreamingServer[TerminalRequest, TerminalResponse]) error
	// Reports whether the box agent answers on its channel.
	CheckBox(context.Context, *CheckBoxRequest) (*CheckBoxResponse, error)
	// Restarts the box (for example after its agent became unavailable) and
	// opens it again through the resume rules: the local home is kept, never
	// restored over while it has unsaved changes.
	RestartBox(context.Context, *RestartBoxRequest) (*RestartBoxResponse, error)
	// The agent channel of a box open here (ADR 0010): its address on this
	// machine's loopback, the certificate the agent presents and the token.
	// Only for the owner of this socket; a Mac fetches it from a server's
	// runner over SSH and keeps it in memory.
	GetChannel(context.Context, *GetChannelRequest) (*GetChannelResponse, error)
	// The box's save state, derived only from what is recorded (the last
	// saved snapshot, the dirty flag, a save in progress) and where it runs.
	GetBoxState(context.Context, *GetBoxStateRequest) (*GetBoxStateResponse, error)
	// The box's state as it changes: the current state at once, then a
	// message whenever anything in it changes, and the state again every 30 s
	// as a heartbeat. The stream ends when portenvd stops (ADR 0014).
	WatchBoxState(*WatchBoxStateRequest, grpc.ServerStreamingServer[WatchBoxStateResponse]) error
	// The system's network status, as the app sees it (NWPathMonitor on the
	// Mac). A fresh "down" (from a running app, at most 30 s old) opens a
	// box offline at once, without probing storage; anything else probes.
	SetNetworkPath(context.Context, *SetNetworkPathRequest) (*SetNetworkPathResponse, error)
	// The system woke from sleep: check every open box's agent channel and
	// restart a box whose channel is gone (its home stays: rule 3), so a
	// dropped channel never sits unnoticed until the next save.
	Woke(context.Context, *WokeRequest) (*WokeResponse, error)
	// Try the box's packages that couldn't be installed again now.
	RetryPackages(context.Context, *RetryPackagesRequest) (*RetryPackagesResponse, error)
	// Keys the app read from the Keychain for a box, held in memory only:
	// portenvd never reads the Keychain interactively, so when a key needs the
	// person's approval it fails fast and the app (in front of them) reads it.
	ProvideKeys(context.Context, *ProvideKeysRequest) (*ProvideKeysResponse, error)
	// Portenv is relaunching (an update): stop serving without closing any
	// box. Boxes and their programs keep running, and the next portenvd
	// takes them over (ADR 0014). Quitting (Cmd-Q) still closes and saves.
	Relaunch(context.Context, *RelaunchRequest) (*RelaunchResponse, error)
	// The servers a box can move to (Move To), as user@host.
	ListServers(context.Context, *ListServersRequest) (*ListServersResponse, error)
	// The Keychain items the app reads for a box (service
	// dev.portenv.repository): its repository key, and its storage keys.
	GetKeyIDs(context.Context, *GetKeyIDsRequest) (*GetKeyIDsResponse, error)
	// An autosave now (the Phase 0 CLI's save, moved here in 1.1).
	SaveNow(context.Context, *SaveNowRequest) (*SaveNowResponse, error)
	// Every save of the box, oldest first: autosaves, save points, closes and
	// orphaned saves, with the machine that made each.
	ListSaves(context.Context, *ListSavesRequest) (*ListSavesResponse, error)
	// Clear old lease tags and apply retention; with prune, also delete data
	// no save uses. For an idle box.
	Housekeep(context.Context, *HousekeepRequest) (*HousekeepResponse, error)
	// Quit Anyway: the box couldn't be saved before Portenv quits. portenvd
	// records the quit marker and keeps retrying the save in the background
	// (30 s, 1, 2 and 5 minutes, then every 5) until one succeeds; then it
	// closes the box and releases the lease. Until then the lease stays with
	// this Mac. Opening the box first stops the retries and saves it first
	// thing ("Portenv quit before saving").
	LeaveUnsaved(context.Context, *LeaveUnsavedRequest) (*LeaveUnsavedResponse, error)
	// Boxes saved in the background after Quit Anyway since the app last
	// asked: the app shows one notification for each. Given out once.
	TakeSavedAfterQuit(context.Context, *TakeSavedAfterQuitRequest) (*TakeSavedAfterQuitResponse, error)
	// The box's tabs (its terminal's tmux windows), through the box agent.
	// The session is "main" when empty.
	ListTabs(context.Context, *ListTabsRequest) (*ListTabsResponse, error)
	NewTab(context.Context, *NewTabRequest) (*NewTabResponse, error)
	CloseTab(context.Context, *CloseTabRequest) (*CloseTabResponse, error)
	RenameTab(context.Context, *RenameTabRequest) (*RenameTabResponse, error)
	SelectTab(context.Context, *SelectTabRequest) (*SelectTabResponse, error)
	// The tabs at once, then whenever they change. The stream ends when the
	// box closes or its agent goes away; the app watches again.
	WatchTabs(*WatchTabsRequest, grpc.ServerStreamingServer[WatchTabsResponse]) error
	// Makes a new box from keys the app made and stored in the Keychain (ADR
	// 0019): writes no key to disk, creates the repository with the box's
	// repository key, adds the recovery-derived key, checks both, and only
	// then writes the box's config. Idempotent on box_id: calling again after
	// a failure or a crash resumes where it stopped. Never logged.
	CreateBox(context.Context, *CreateBoxRequest) (*CreateBoxResponse, error)
	// Forgets an unfinished creation (ListBoxes shows it as creating): the
	// name is free again. The repository it may have left, with no snapshot,
	// is never deleted.
	DiscardCreation(context.Context, *DiscardCreationRequest) (*DiscardCreationResponse, error)
	// Restores a box on this Mac with only the recovery key (ADR 0019): opens
	// the repository with the recovery-derived password, adds this Mac's new
	// repository key, checks it, and writes the box's config. Idempotent on
	// box_id. Never logged.
	RecoverBox(context.Context, *RecoverBoxRequest) (*RecoverBoxResponse, error)
	// Checks a typed recovery key before the app refills its pool from it
	// (ADR 0019): the recovery-derived passwords, one per box ID, are tried
	// against the boxes here that carry a recovery key. Read-only. Never
	// logged.
	CheckRecoveryKey(context.Context, *CheckRecoveryKeyRequest) (*CheckRecoveryKeyResponse, error)
	// Where a box is open when it isn't this Mac (2.3, the lease sheet): the
	// place, its newest save, and whether it answers. A known server is asked
	// with `portenv app ping`, within 2 s; another machine can't be asked.
	// OpenBox's refusal for a box open elsewhere carries the trailer
	// portenv-refusal: open-elsewhere, and the app asks this then.
	GetPlacement(context.Context, *GetPlacementRequest) (*GetPlacementResponse, error)
	// One tab's terminal (ADR 0020), relayed to the workspace helper's
	// TabTerminal as Terminal is: same socket, same box routing, on this Mac
	// or on a server. The first message must be open. portenvd sets the
	// stream's author from the connection's caller; nothing in the request
	// can, and the open has no author field.
	TabTerminal(grpc.BidiStreamingServer[TabTerminalRequest, TabTerminalResponse]) error
	// A server's host key (2.9, ADR 0021, R-0180), found through ssh itself
	// and compared, read only, with this Mac's SSH known hosts: the same key
	// confirms the server; a different one marks it changed. A server that
	// isn't confirmed is never contacted.
	ScanServerKey(context.Context, *ScanServerKeyRequest) (*ScanServerKeyResponse, error)
	// Pin the key the last scan found, given the fingerprint the person saw.
	// A changed key can't be trusted: only Forget gets past it.
	TrustServerKey(context.Context, *TrustServerKeyRequest) (*TrustServerKeyResponse, error)
	// Drop the server's pinned key: it is unconfirmed again.
	ForgetServerKey(context.Context, *ForgetServerKeyRequest) (*ForgetServerKeyResponse, error)
	// A made key's private half (2.9 1b, ADR 0021), read by the app from the
	// Keychain and held in portenvd's memory only, like ProvideKeys: never
	// written, never logged. It signs in once per shared connection, through
	// an agent of portenvd's own for that one run.
	ProvideServerKey(context.Context, *ProvideServerKeyRequest) (*ProvideServerKeyResponse, error)
	// Add a Server's Check (2.9, ADR 0021 §3): a read-only probe over the
	// server's pinned SSH connection, one line per question; each failure
	// says what to do, in Portenv's words, never the server's. It changes
	// nothing on the server.
	CheckServer(context.Context, *CheckServerRequest) (*CheckServerResponse, error)
	// Whether this Mac's box engine answers (Docker Desktop is running), for
	// Welcome's Docker card and the state line (R-0098). It only asks the
	// engine: it never starts anything. portenvd gives the engine 1.5 s;
	// the app waits 3 s for the answer.
	GetEngine(context.Context, *GetEngineRequest) (*GetEngineResponse, error)
	// ADR 0022: the agent team. Every call names the workspace; only the app,
	// in front of the person, makes them.
	// A workspace's agents, from its project's agent files.
	ListAgents(context.Context, *ListAgentsRequest) (*ListAgentsResponse, error)
	// The agents, then every change, board message and decision, from a
	// cursor.
	WatchTeam(*WatchTeamRequest, grpc.ServerStreamingServer[WatchTeamResponse]) error
	// Starts an agent whose file is approved and valid.
	StartAgent(context.Context, *StartAgentRequest) (*StartAgentResponse, error)
	// Stops an agent at once: its tmux server and every process of its user.
	StopAgent(context.Context, *StopAgentRequest) (*StopAgentResponse, error)
	// The owner's Fetch (ADR 0022 §2a): an agent's branch, agent/<id> in its
	// own clone, into the project as refs/remotes/agents/<id>, by the safe
	// fetch that never opens the agent's repository as work.
	FetchAgentBranch(context.Context, *FetchAgentBranchRequest) (*FetchAgentBranchResponse, error)
	// Approve or Decline, the owner's answer to a pending decision.
	AnswerDecision(context.Context, *AnswerDecisionRequest) (*AnswerDecisionResponse, error)
	// An agent file's content and the content last approved, for Approve's
	// diff and its runner line.
	GetAgentFile(context.Context, *GetAgentFileRequest) (*GetAgentFileResponse, error)
	// Pins an agent file's content (§3): the hash must be what the app showed.
	ApproveAgentFile(context.Context, *ApproveAgentFileRequest) (*ApproveAgentFileResponse, error)
	// The owner's message to an agent.
	SendMessage(context.Context, *SendMessageRequest) (*SendMessageResponse, error)
	// Removes an agent. Its files stay until the owner approves a
	// DECISION_KIND_DELETE_AGENT_FILES decision (§1).
	RemoveAgent(context.Context, *RemoveAgentRequest) (*RemoveAgentResponse, error)
	// The Agent files view (§2): list, open and add, done as the agent's user.
	ListAgentFiles(context.Context, *ListAgentFilesRequest) (*ListAgentFilesResponse, error)
	ReadAgentFile(*ReadAgentFileRequest, grpc.ServerStreamingServer[ReadAgentFileResponse]) error
	// Drag and drop. Refused past the agent's quota.
	AddAgentFiles(grpc.ClientStreamingServer[AddAgentFilesRequest, AddAgentFilesResponse]) error
	// Pauses or resumes one of an agent's routines (R-0258).
	SetRoutinePaused(context.Context, *SetRoutinePausedRequest) (*SetRoutinePausedResponse, error)
	// Attachments (ADR 0030), the owner only: an agent caller is refused.
	// ReadAttachment streams one from this Mac's store, the record first.
	ReadAttachment(*ReadAttachmentRequest, grpc.ServerStreamingServer[ReadAttachmentResponse]) error
	// The owner's files for agents (drop or Attach…): stored once, copied
	// into each agent's ~/inbox/owner/<time>/, one board notice per agent.
	SendAttachments(grpc.ClientStreamingServer[SendAttachmentsRequest, SendAttachmentsResponse]) error
	// Remove from this Mac: deletes one attachment's bytes; its records stay.
	RemoveAttachment(context.Context, *RemoveAttachmentRequest) (*RemoveAttachmentResponse, error)
	mustEmbedUnimplementedDaemonServiceServer()
}

